fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,
    liquidation_params: &LiquidationParams,

    mut available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    now: u64,

    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());

    let debt_name = type_name::with_defining_ids<DebtType>();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();

    // update all assets interest in the obligation
    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);

    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
        liquidation_params,
        obligation,
        emode_group,
        reserves,
        coin_decimals_registry,
        available_repay_coin.value(),
        x_oracle,
        clock,
    );

    // calculate how much collateral can be seized first
    let obligation_latest_borrow_amount = obligation.debt(debt_name)
        .unsafe_debt_amount()
        // repay a bit more
        .ceil();
    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
        available_repay_coin.split(refund_amount, ctx)
    } else {
        sui::coin::zero(ctx)
    };

    // NOTE: disable rate limit

    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 

    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
        exchange_rate,
        liquidation_params.liquidation_incentive,
        available_repay_coin.value(),
        emode_group.get_oracle_base_token(),
        x_oracle,
        coin_decimals_registry,
        clock,
    );

    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
    if (total_ctokens < seized_ctokens) {
        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
            .mul_u64(available_repay_coin.value())
            // repay a bit more
            .ceil();
        let refund = available_repay_coin.value() - expected_repay_amount;

        refund_coins.join(available_repay_coin.split(refund, ctx));
        seized_ctokens = total_ctokens;
    };

    // at this stage, even if there is residual, it should be a very small amount, let the protocol consume the residual
    let _residual = obligation.unsafe_repay_debt_only<MarketType, DebtType>(available_repay_coin.value());

    let ctoken_balance = obligation.withdraw_ctokens<MarketType, CollateralType>(seized_ctokens);
    let ctoken_balance_amount = ctoken_balance.value();
    let refund_balance = collateral_reserve.liquidate_ctokens<MarketType, CollateralType>(
        ctoken_balance.into_coin(ctx),
        liquidation_params.liquidation_revenue_factor,
    );

    let obligation_new_borrow_amount = if (!obligation.has_debt(debt_name)) { float::zero() } else { obligation.debt(debt_name).unsafe_debt_amount() };
    emode_group.update_asset_borrow(debt_name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let debt_reserve = reserves.load_mut_by_type(debt_name);
    debt_reserve.repay_amount<MarketType, DebtType>(available_repay_coin);

    try_stop_borrow_deleverage<MarketType, DebtType>(id, obligation.emode_group(), emode_group, debt_name);
    try_stop_collateral_deleverage<MarketType, CollateralType>(id, reserves, collateral_name);

